use numtheory::{fib, is_prime, prime_factors};

#[test]
fn test_fib_base_cases() {
    assert_eq!(fib(0), 0);
    assert_eq!(fib(1), 1);
}

#[test]
fn test_fib_sequence() {
    assert_eq!(fib(10), 55);
    assert_eq!(fib(20), 6765);
}

#[test]
fn test_is_prime() {
    assert!(!is_prime(1));
    assert!(is_prime(2));
    assert!(is_prime(17));
    assert!(!is_prime(18));
}

#[test]
fn test_prime_factors() {
    assert_eq!(prime_factors(12), vec![2, 3]);
    assert_eq!(prime_factors(30), vec![2, 3, 5]);
    assert_eq!(prime_factors(7), vec![7]);
}

#[test]
fn test_prime_factors_one() {
    assert_eq!(prime_factors(1), vec![]);
}

