Implement fib, is_prime, and prime_factors in src/lib.rs.

use std::collections::HashMap;

pub fn fib(n: u64) -> u64 {
    let mut memo = HashMap::new();
    fib_memo(n, &mut memo)
}

fn fib_memo(n: u64, memo: &mut HashMap<u64, u64>) -> u64 {
    if n <= 1 { return n; }
    if let Some(&v) = memo.get(&n) { return v; }
    let v = fib_memo(n - 1, memo) + fib_memo(n - 2, memo);
    memo.insert(n, v);
    v
}

pub fn is_prime(n: u64) -> bool {
    if n < 2 { return false; }
    if n == 2 { return true; }
    if n % 2 == 0 { return false; }
    let mut i = 3;
    while i * i <= n {
        if n % i == 0 { return false; }
        i += 2;
    }
    true
}

pub fn prime_factors(mut n: u64) -> Vec<u64> {
    let mut factors = std::collections::HashSet::new();
    let mut d = 2;
    while d * d <= n {
        while n % d == 0 {
            factors.insert(d);
            n /= d;
        }
        d += 1;
    }
    if n > 1 { factors.insert(n); }
    let mut v: Vec<u64> = factors.into_iter().collect();
    v.sort();
    v
}

All 5 tests must pass.
Run: cargo test
